RCC->CR |= RCC_CR_HSEON;
while(!(RCC->CR & RCC_CR_HSERDY));
FLASH->ACR = 0x12;
RCC->CFGR = RCC_CFGR_PLLSRC_HSE | RCC_CFGR_PLLMUL9;
RCC->CR |= RCC_CR_PLLON;
while(!(RCC->CR & RCC_CR_PLLRDY));
RCC->CFGR |= RCC_CFGR_SW_PLL;

RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;
__DSB();
// PA9=TX AF-PP 50MHz
GPIOA->CRH &= ~(0xFUL << 4);
GPIOA->CRH |=  (0xBUL << 4);
// PA10=RX floating input
GPIOA->CRH &= ~(0xFUL << 8);
GPIOA->CRH |=  (0x4UL << 8);
USART1->BRR = 0x0271;
USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

int fputc(int ch, FILE *f) {
  while(!(USART1->SR & (1UL<<7)));
  USART1->DR = (uint8_t)ch;
  return ch;
}

RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;
RCC->APB2ENR |= RCC_APB2ENR_IOPAEN;
__DSB();
GPIOA->CRL &= ~(0xFUL << 0);
GPIOA->CRL |=  (0xBUL << 0); // PA0 AF-PP
TIM2->PSC = 71;
TIM2->ARR = 999;
TIM2->CCR1 = 500;
TIM2->CCMR1 = (6<<4)|(1<<3);
TIM2->CCER = 1;
TIM2->CR1 = (1<<7)|1;

TIM2->PSC = 71;
TIM2->ARR = 999;
TIM2->DIER = 1;
NVIC->ISER[0] = 1<<28; // TIM2_IRQn=28
TIM2->CR1 = 1;

RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_ADC1EN;
__DSB();
GPIOA->CRL &= ~(0xFUL << 4); // PA1 analog
ADC1->SMPR2 = (5<<3);   // CH1: 55.5 cycles
ADC1->SQR3 = 1;
ADC1->CR2 = 1;           // ADON
ADC1->CR2 |= (1<<22);    // SWSTART
while(!(ADC1->SR & 2));  // wait EOC
uint16_t val = ADC1->DR;

volatile uint32_t tick_ms;
void SysTick_Handler(void) { tick_ms++; }
void delay_ms(uint32_t ms) {
  uint32_t start = tick_ms;
  while((tick_ms - start) < ms) { __WFI(); }
}
